import numpy as np
from scipy.optimize import minimize

def objective(k, n):
    # k is a list [k_1, k_2, ..., k_{n-1}]
    # sum = 1/k_1 + \sum_{j=1}^{n-2} \frac{k_j}{k_{j+1}(1+k_j)}
    res = 1.0 / k[0]
    for j in range(1, n-1):
        res += k[j-1] / (k[j] * (1 + k[j-1]))
    return -res

def solve():
    for n in range(2, 10):
        # Constraints: k_i >= 1
        cons = []
        for i in range(n-1):
            cons.append({'type': 'ineq', 'fun': lambda k, i=i: k[i] - 1})

        # Initial guess: all k_i = 1
        k0 = np.ones(n-1)
        res = minimize(objective, k0, args=(n,), constraints=cons, bounds=[(1, None)] * (n-1))
        print(f"n={n}, max_sum={-res.fun:.4f}, k={res.x}")

solve()

